feedbackvariables.text:
/* Node 1: Check complete correctness of both sets (4) */
node1_test: if ans1>3 and ans1/3=(ans2+4)/4 and ans1/3=(ans3+5)/5 and ans4>3 and ans4/3=(ans5+4)/4 and ans4/3=(ans6+5)/5 then 1 else 0;

/* Node 2: Worked solution */

/* Node 3: Check correctness of first set (2) */
node3_test: if ans1>3 and ans1/3=(ans2+4)/4 and ans1/3=(ans3+5)/5 then 1 else 0;

/* Node 4: Check if first set is wrong by giving sides of ABC (1) */
node4_test: if ans1>3 and ans1/3=ans2/4 and ans1/3=ans3/5 then 1 else 0;

/* Node 5: Check if first set has any two sides with correct ratios (1) */
node5_test: if ans1>3 and (ans1/3=(ans2+4)/4 or ans1/3=(ans3+5)/5 or (ans2+4)/4=(ans3+5)/5) then 1 else 0;

/* Node 6: Check combination of errors at node4 and node5 (0 by feedback) */
node6_test: if ans1>3 and (ans1/3=ans2/4 or ans1/3=ans3/5 or ans2/4=ans3/5) then 1 else 0;

/* Node 7: Check correctness of second set (2) */
node7_test: if ans4>3 and ans4/3=(ans5+4)/4 and ans4/3=(ans6+5)/5 then 1 else 0;

/* Node 8: Check if second set is wrong by giving sides of ABC (1) */
node8_test: if ans4>3 and ans4/3=ans5/4 and ans4/3=ans6/5 then 1 else 0;

/* Node 9: Check if second set has any two sides with correct ratios (1) */
node9_test: if ans4>3 and (ans4/3=(ans5+4)/4 or ans4/3=(ans6+5)/5 or (ans5+4)/4=(ans6+5)/5) then 1 else 0;

/* Node 10: Check combination of errors at node8 and node9 (0 by feedback) */
node10_test: if ans4>3 and (ans4/3=ans5/4 or ans4/3=ans6/5 or ans5/4=ans6/5) then 1 else 0;
